/** Synthetic update fixtures generated by the actual shipped 0.71 source. */
import fs from 'node:fs/promises';
import {execFileSync} from 'node:child_process';
import assert from 'node:assert/strict';
import {createServer} from 'vite';
const [root,output]=process.argv.slice(2);
const source='5be1d7b2bca92683593265fa2ab346c4eb173015';
assert(root&&output);assert.equal(execFileSync('git',['rev-parse','HEAD'],{cwd:root,encoding:'utf8'}).trim(),source);
const server=await createServer({root,server:{middlewareMode:true,hmr:false,watch:null}});
try{
 const R=await server.ssrLoadModule('/src/core/rules.ts'),P=await server.ssrLoadModule('/src/core/profile.ts'),M=await server.ssrLoadModule('/src/core/monetization.ts'),E=await server.ssrLoadModule('/src/core/experiment.ts');
 const cases=[];
 for(const [i,dealer] of ['director-challenge-v1','director-challenge-v2'].entries()){
  let g=R.newGame(91072001+i,`synthetic-upgrade-${i}`,dealer);g={...g,scoringVersion:'festival-v4',seriesBonusVersion:1,comparisonMode:'manual'};
  if(!i){for(let n=0;n<4;n++){
   const m=g.tray.flatMap((s,slot)=>s.used?[]:R.placements(g.board,R.shapeById(s.shapeId)).map(p=>({...p,slot})))[0];
   assert(m);g=R.applyMove(g,m,g.revision,false,{activeMs:n*1500}).state;
  }}else{
   g={...g,board:Array(64).fill(1),tray:[{shapeId:'O3-0',color:2,used:false},{shapeId:'O3-0',color:3,used:true},{shapeId:'O3-0',color:4,used:true}],moves:49,revision:49,score:700,status:'over'};
   assert.equal(R.hasMove(g.board,g.tray),false);
  }
  let p=P.createProfile(g);p={...p,tutorialStep:4,best:g.score,progressionBest:g.score,freeHints:1,earnedHints:2,settings:{...p.settings,sound:false,calm:true,haptics:false}};
  p=E.ensureExperiment(p,100,false,'synthetic-existing-installation');p.experiment.manualDealer=dealer;
  p=M.applyReceipt(M.prepareReward(p,'synthetic-old-hints','hints'),{id:'synthetic-old-hints-receipt',intentId:'synthetic-old-hints'});
  if(i)p=M.applyReceipt(M.prepareReward(p,'synthetic-old-revive','revive'),{id:'synthetic-old-revive-receipt',intentId:'synthetic-old-revive'});
  p.revision=20;assert(P.validProfile(p));assert.equal(p.earnedHints,5);
  const move=p.game.tray.flatMap((s,slot)=>s.used?[]:R.placements(p.game.board,R.shapeById(s.shapeId)).map(pos=>({...pos,slot})))[0];assert(move);
  const next=R.applyMove(p.game,move,p.game.revision,false,{activeMs:p.game.challengeV2State?.activeMs??p.game.challengeState?.activeMs??0}).state;
  cases.push({name:i?'0.71-earned-revive':'0.70-unfinished',profile:p,nextMove:move,expectedNext:{board:next.board,moves:next.moves,score:next.score,reviveUsed:next.reviveUsed,recoveryDeals:next.rhythm?.recoveryDeals}});
 }
 await fs.writeFile(output,JSON.stringify({provenance:'Synthetic fixtures generated by the actual 0.71 source, not owner recordings',source,sourceTree:execFileSync('git',['rev-parse','HEAD^{tree}'],{cwd:root,encoding:'utf8'}).trim(),appVersion:'0.71.0-preview',cases},null,2)+'\n');
 console.log('Generated two valid old-source profiles with preserved hints/receipt/revive rights');
}finally{await server.close();}
